def norm(g):
    m=[r[:] for r in g]; h=len(m);w=len(m[0]); 
    # remove zero rows/cols then normalize color
    import numpy as np
    a=np.array(m)
    rows=[i for i,r in enumerate(a) if any(r!=0)]
    cols=[j for j in range(w) if any(r[j]!=0 for r in a)]
    return [[int(x) for x in np.take(np.take(a,rows,axis=0),cols)] for r in np.take(np.take(a,rows,axis=0),cols)]
