    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def comps(g,col):
    a=np.array(g); h,w=a.shape; seen=np.zeros_like(a,bool); res=[]
    for i in range(h):
        for j in range(w):
            if a[i,j]==col and not seen[i,j]:
                st=[(i,j)]; seen[i,j]=True; comp=[]
                while st:
                    y,x=st.pop(); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and a[ny,nx]==col and not seen[ny,nx]:
                            seen[ny,nx]=True; st.append((ny,nx))
                ys=[q[0] for q in comp]; xs=[q[1] for q in comp]
                o=[[int(a[y,x]) for x in range(min(xs),max(xs)+1)] for y in range(min(ys),max(ys)+1)]
                res.append(((min(ys),min(xs)),o))
    return res
