def solve(a, thresh=2):
    h,w=a.shape
    cc=collections.defaultdict(list)
    for y in range(h):
        for x in range(w):
            if a[y,x]!=0: cc[int(a[y,x])].append((y,x))
    kept=[]
    for col_,cells_ in cc.items():
        seen=np.zeros_like(a,bool); comps=[]
        for p in cells_:
            if seen[p]: continue
            st=[p]; comp={p}; seen[p]=True
            while st:
                q=st.pop(); comp.add(q)
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    r2=(q[0]+dy,q[1]+dx)
                    if 0<=r2[0]<h and 0<=r2[1]<w and a[r2]==col_ and not seen[r2]:
                        seen[r2]=True; st.append(r2)
            if len(comp)>=thresh: comps.append(comp)
        # merge: comps of same color adjacent within gap <=1
        merged=[]
        rem=set()
        for c0 in comps:
            if c0 in rem: continue
            stack=[c0]; bucket=set(c0)
            while stack:
                compb=stack.pop()
                for c2 in comps:
                    if c2 in rem or c2==compb: continue
                    inter=bool(set(c0)&set(c2))
                    if not inter: continue
                    # distance check
                    rsA=sorted({q[0] for q in c0}); csA=sorted({q[1] for q in c0})
                    rsB=sorted({q[0] for q in c2}); csB=sorted({q[1] for q in c2})
                    dr=min(abs(rsA[-1]-rsB[0]),abs(rsB[-1]-rsA[0])); dc=min(abs(csA[-1]-csB[0]),abs(csB[-1]-csA[0]))
                    if dr>=2 or dc>=2: continue
                    bucket|=set(c2); stack.append(c2)
            rem|=bucket; merged.append(bucket)
        kept+=merged
    U=set()
    for c0 in kept:
        for q in c0: U.add(q)
    rs=[q[0] for q in U]; cs=[q[1] for q in U]
    r0,c0_=min(rs),min(cs)
    out=np.full((max(rs)-r0+1,max(cs)-c0_+1),0)
    for (rr,ccx) in U: out[rr-r0,ccx-c0_]=int(a[rr,ccx])
    return out.tolist()
