def comps(M, v):
    H,W=M.shape; seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if M[r,c]==v and (r,c) not in seen:
                q=[(r,c)]; seen.add((r,c)); comp=[]
                while q:
                    a,b=q.pop(); comp.append((a,b))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        n=(a+dr,b+dc)
                        if 0<=n[0]<H and 0<=n[1]<W and M[n]==v and n not in seen:
